import json
import os
from datetime import datetime

def generate_objects():
    num_objects = int(input("Digite a quantidade total de objetos que deseja gerar: "))
    
    directory = input("Digite o caminho do diretório onde deseja salvar o arquivo JSON: ")
    os.makedirs(directory, exist_ok=True)
    
    file_name = input("Digite o nome do arquivo (sem a extensão .json): ")

    file_path = os.path.join(directory, f"{file_name}.json")
    
    # Definindo o ano e mês atuais para o campo "anoMes"
    ano_mes = int(datetime.now().strftime('%Y%m'))

    dividas = []
    for i in range(num_objects):
        data = {
            "dataContrato": "2024-10-01",
            "dataLeiAutorizativa": "2024-10-01",
            "descricaoEmenta": "Objetivo Exemplo",
            "documentos": [
                {
                    "arquivo": "",
                    "nomeArquivo": f"exemplo_{i+1}.pdf"
                }
            ],
            "numeroCnpjContratado": "92816560000307",
            "numeroContrato": str(13896 + i),  # Incrementando o numeroContrato
            "numeroLeiAutorizativa":str(111/111+ i),
            "tipoDivida": 8,
            "valorAutorizado": 11009.79,
            "valorContratado": 11009.79
        }
        
        dividas.append(data)

    final_data = {
        "anoMes": ano_mes,
        "dividas": dividas,
        "quantidadeDivida": num_objects,
        "quantidadeDocumentoDivida": num_objects  # Assumindo que há 1 documento por dívida
    }

    with open(file_path, 'w') as f:
        json.dump(final_data, f, indent=4)
    
    print(f"Arquivo {file_path} salvo com sucesso!")

generate_objects()